import api from './api';

export const adminService = {
  // Get all vendors
  getAllVendors: async () => {
    try {
      const response = await api.get('/api/admin/vendors');
      return response;
    } catch (error) {
      throw error;
    }
  },

  // Get vendors by region
  getVendorsByRegion: async (region) => {
    try {
      const response = await api.get(`/api/admin/vendors/region/${region}`);
      return response;
    } catch (error) {
      throw error;
    }
  },

  // Get all applications
  getAllApplications: async () => {
    try {
      const response = await api.get('/api/admin/applications');
      return response;
    } catch (error) {
      throw error;
    }
  },

  // Get applications by status
  getApplicationsByStatus: async (status) => {
    try {
      const response = await api.get(`/api/admin/applications/status/${status}`);
      return response;
    } catch (error) {
      throw error;
    }
  },

  // Get admin dashboard data
  getDashboard: async () => {
    try {
      const response = await api.get('/api/admin/dashboard');
      return response;
    } catch (error) {
      throw error;
    }
  }
};
